import assert from 'node:assert/strict';
import {createServer} from 'node:https';
import {readFileSync,mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {once} from 'node:events';
import {CapabilityRegistry,createCapabilityServer} from '../../../core/dist/index.js';
import {SqliteAgentRuns,SqliteAgentTokenBudget,SqliteAgentBudgetRecoveryDiscovery,AgentBudgetRecovery,createBudgetHttpsVerifier,SqliteAgentRunMetrics,registerBudgetRecoveryDiscovery,registerBudgetRecovery,registerBudgetRecoveryPending,registerBudgetRecoveryHistory} from '../../dist/index.js';
const scope={tenantId:'tenant',agentId:'agent'},other={tenantId:'other',agentId:'agent'},target={scope,runId:'run',maxTokens:100},cost={currency:'USD',maxMicros:1000},tls=new URL('../../../core/test/fixtures/capability-tls/',import.meta.url),dir=mkdtempSync(join(tmpdir(),'budget-workflow-')),path=join(dir,'db.sqlite');let runs,budget,foreign,discovery,metrics,capabilityServer,providerServer;
try{runs=new SqliteAgentRuns(path);const initialize=selected=>{let run=runs.create(selected,'run',{definitionVersion:1,maxAttempts:2,deadline:1000},0);run=runs.claim(selected,'run',run.revision,'worker',100,1);const ledger=new SqliteAgentTokenBudget(path,{scope:selected,runId:'run',leaseToken:run.leaseToken,maxTokens:100,cost,clock:()=>2});ledger.reserve('call',40,500);run=runs.settle(selected,'run',run.revision,run.leaseToken,'uncertain',3);return {run,ledger};};const local=initialize(scope),isolated=initialize(other);budget=local.ledger;foreign=isolated.ledger;let response={found:false};const lookups=[];providerServer=createServer({key:readFileSync(new URL('server-key.pem',tls)),cert:readFileSync(new URL('server-cert.pem',tls))},async(req,res)=>{const chunks=[];for await(const chunk of req)chunks.push(chunk);lookups.push({authorization:req.headers.authorization,body:JSON.parse(Buffer.concat(chunks))});res.writeHead(200,{'content-type':'application/json'});res.end(JSON.stringify(response));});providerServer.listen(0,'127.0.0.1');await once(providerServer,'listening');const verify=createBudgetHttpsVerifier({target,url:`https://127.0.0.1:${providerServer.address().port}/lookup`,bearerToken:'a'.repeat(32),timeoutMs:5000,maxPending:1,interpret:(body,context)=>body.found===true&&body.callId===context.callId&&body.currency===context.cost?.currency?{usedTokens:body.usedTokens,usedCostMicros:body.usedCostMicros}:undefined}),recovery=new AgentBudgetRecovery({budget,target,authorize:(who,_target,action)=>action==='history'?who.principalId==='auditor':who.principalId==='operator',verify,timeoutMs:5000,maxPending:2});discovery=new SqliteAgentBudgetRecoveryDiscovery(path,{scope,authorize:who=>who.principalId==='operator'});metrics=new SqliteAgentRunMetrics(path,{scope,includeBudgetBacklog:true,authorize:()=>true});const registry=new CapabilityRegistry(()=>{}),base={scope,runId:'run',recovery};registerBudgetRecoveryDiscovery(registry,{discovery,scope,operationId:'discover',path:'/discover',limit:10,authorize:who=>who.principalId==='operator'});registerBudgetRecoveryPending(registry,{...base,operationId:'pending',path:'/pending',limit:10});registerBudgetRecovery(registry,{...base,operationId:'recover',path:'/recover'});registerBudgetRecoveryHistory(registry,{...base,operationId:'history',path:'/history',limit:10});const identities={operator:{tenantId:'tenant',principalId:'operator'},auditor:{tenantId:'tenant',principalId:'auditor'},other:{tenantId:'other',principalId:'operator'}};capabilityServer=createCapabilityServer(registry,req=>identities[(req.headers.authorization??'').replace('Bearer ','')],()=>{});capabilityServer.listen(0,'127.0.0.1');await once(capabilityServer,'listening');const call=(name,principal,query)=>fetch(`http://127.0.0.1:${capabilityServer.address().port}/capabilities/${name}/invoke`,{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${principal}`},body:JSON.stringify({origin:'ui',input:{query}})});const result=async(name,principal,query)=>{const res=await call(name,principal,query);assert.equal(res.status,200,await res.clone().text());return (await res.json()).result;};
 assert.equal((await call('discover','invalid',{})).status,401);assert.equal((await call('discover','other',{})).status,403);assert.deepEqual((await result('discover','operator',{})).items,[{runId:'run',runStatus:'uncertain',reserved:1}]);assert.equal((await result('pending','operator',{})).items[0].callId,'call');assert.equal((await metrics.budgetBacklog(identities.operator)).find(row=>row.runStatus==='uncertain').count,1);assert.throws(()=>runs.reconcile(scope,'run',local.run.revision,'retry',4),/Token usage requires reconciliation/);assert.equal((await call('recover','operator',{callId:'call',reference:'provider-case',usedTokens:0})).status,400);assert.deepEqual(await result('recover','operator',{callId:'call',reference:'provider-case'}),{outcome:'unknown'});assert.equal(budget.get('call').status,'reserved');assert.equal((await call('history','operator',{})).status,403);assert.deepEqual((await result('history','auditor',{})).items,[]);response={found:true,callId:'call',currency:'USD',usedTokens:17,usedCostMicros:125};assert.deepEqual(await result('recover','operator',{callId:'call',reference:'provider-case'}),{outcome:'reconciled'});const history=(await result('history','auditor',{})).items;assert.equal(history.length,1);assert.equal(history[0].principalId,'operator');assert.equal(history[0].reference,'provider-case');assert.equal(history[0].usedTokens,17);assert.equal(history[0].usedCostMicros,125);assert.deepEqual((await result('pending','operator',{})).items,[]);assert.deepEqual((await result('discover','operator',{})).items,[]);assert.equal((await metrics.budgetBacklog(identities.operator)).find(row=>row.runStatus==='uncertain').count,0);assert.equal(runs.reconcile(scope,'run',local.run.revision,'retry',4).status,'queued');assert.equal(foreign.get('call').status,'reserved');assert.equal(foreign.getCost('call').status,'reserved');assert.equal(lookups.length,2);assert.equal(lookups[1].authorization,'Bearer '+'a'.repeat(32));assert.equal(lookups[1].body.callId,'call');
}finally{if(capabilityServer){capabilityServer.closeAllConnections();await new Promise(resolve=>capabilityServer.close(resolve));}if(providerServer){providerServer.closeAllConnections();await new Promise(resolve=>providerServer.close(resolve));}metrics?.close();discovery?.close();foreign?.close();budget?.close();runs?.close();rmSync(dir,{recursive:true,force:true});}
